mapper.select:
SELECT id, group_id, user_id, role, muted, created_at
FROM chat_group_member
WHERE group_id = #{groupId}
  AND user_id = #{userId}
LIMIT 1

mapper.update:
UPDATE chat_group_member
SET muted = #{muted}
WHERE group_id = #{groupId}
  AND user_id = #{userId}

UPDATE chat_group_member
SET role = #{role}
WHERE group_id = #{groupId}
  AND user_id = #{userId}

mapper.delete:
DELETE FROM chat_group_member
WHERE group_id = #{groupId}
  AND user_id = #{userId}

mapper.select:
SELECT COUNT(1)
FROM chat_group_member
WHERE group_id = #{groupId}
